import { CommonModule, Location } from '@angular/common';
import { Component } from '@angular/core';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { MatMenuModule } from '@angular/material/menu';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSelectModule } from '@angular/material/select';
import { MatTooltipModule } from '@angular/material/tooltip';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { ScrollingModule } from '@angular/cdk/scrolling';
import { TableComponent } from '../../../../../shared/components/myfiles/table/table.component';
import { SkeletonComponent } from '../../../../../shared/components/skeleton/skeleton.component';
import { ActivatedRoute } from '@angular/router';
import { BatchfileService } from '../../../../services/batchfile/batchfile.service';
import { map } from 'rxjs';
import { UserPermissionService } from '../../../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-batchlog',
  standalone: true,
  providers: [BatchfileService],
  imports: [CommonModule, ButtonComponent, IconComponent, MatMenuModule, MatFormFieldModule, MatSelectModule, IconComponent, MatTooltipModule, AvatarComponent, ScrollingModule, TableComponent, SkeletonComponent, MatTooltipModule],
  templateUrl: './batchlog.component.html',
  styleUrl: './batchlog.component.scss'
})
export class BatchlogComponent {
  nCaseid: string;
  cFolder: any;
  public creattype: string;
  sortby: any = 'Newest';
  alphas: any = ['Newest', 'Oldest'];
  loading: boolean = false;
  changedata: any = [];
  dataSource: any = [];

  loglist = [
  ];
  // columns: any = [];
  timePeriods = [
    { key: 'Bundle', dbkey: 'cBundletag', isShow: false, isedit: false, dwidth: 65, width: 50 },
    { key: 'Tab', dbkey: 'cTab', isShow: true, isedit: false, dwidth: 52, width: 70 },
    { key: 'Name', dbkey: 'cFilename', isShow: true, isedit: false, dwidth: 65, width: '*' },
    { key: 'Date', dbkey: 'dIntrestDt', isShow: true, isedit: false, dwidth: 121, width: 70 },
    { key: 'Description', dbkey: 'cDesc', isShow: true, isedit: false, dwidth: 97, width: 80 },
    { key: 'Page', dbkey: 'cRefpage', isShow: true, isedit: false, dwidth: 58, width: 40 },
    { key: 'Kind', dbkey: 'kind', isShow: false, isedit: false, dwidth: 57, width: 30 },
    { key: 'Exhibit', dbkey: 'cExhibitno', isShow: true, isedit: false, dwidth: 90, width: 75 }
  ];
  highlightCol = [];
  constructor(private location: Location, private route: ActivatedRoute, private batchS: BatchfileService, private userPermissions: UserPermissionService) {
    var params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : 0;
    this.getBatchLog();
    userPermissions.userPermissionList(this.nCaseid);
  }

  getBatchLog() {
    this.loading = true;
    this.batchS.getBatchLog(this.nCaseid).then((res: any) => {
      this.loading = false;
      this.loglist = res;
    });
  }


  goBack() {
    this.location.back();
  }

  isChange(y, column) {
    return y["columnDefs"].filter(e => e == y[column]) ? true : false;
  }

  getBatchLogDetail(x) {
    if (x["isShow"]) {
      x["isShow"] = false;
      return;
    } else { x["isShow"] = true; }
    x.loading = true;
    this.batchS.getBatchLogDetail(x.nBlogid).then((res: any) => {
      x.loading = false;
      if (res) {
        
        let cols = JSON.parse('[' + res[0][0].ccolumn + ']');
        let data: any = res[2][0].dynamic_pivot;
        let updatecols: any = res[1];
        const columnMapping = Object.fromEntries(cols);
        this.dataSource = this.updateColumnNames(data, columnMapping, updatecols);
      }
    });
  }


  reqcols: any =
    {
      'drag': { dbkey: 'drag', view: false, edit: false },
      'check': { dbkey: 'check', view: false, edit: false },
      'order': { dbkey: 'order', view: false, edit: false },
      'bundle': { dbkey: 'cBundletag', view: true, edit: false },
      'tab': { dbkey: 'cTab', view: true, edit: false },
      'name': { dbkey: 'cName', view: true, edit: false },
      'link': { dbkey: 'link', view: false, edit: false },
      'relevence': { dbkey: 'link', view: false, edit: false },
      'impact': { dbkey: 'link', view: false, edit: false },
      'page': { dbkey: 'cRefpage', view: true, edit: false },
      'exhibit': { dbkey: 'cExhibitno', view: true, edit: false },
      'kind': { dbkey: 'cKind', view: true, edit: false },
      'date': { dbkey: 'dIntrestDt', view: true, edit: false },
      'desc': { dbkey: 'cDesc', view: true, edit: false },
      'extra': { dbkey: 'dIntrestDt', view: false, edit: false },
    };


  updateColumnNames(data, mapping, updatecols) {
    updatecols.map(e => e.changecol = e.changecol.split(','))
    return data.map((item, i) => {
      const newItem = {};

      for (const [key, value] of Object.entries(item)) {
        const newKey = mapping[key] == 'cFilename' ? 'cName' : mapping[key] || key; // Get new key from mapping, or use the original key if not found
        newItem[newKey] = value;
        if (i == 0) {
          updatecols.forEach((uel) => {
            uel.changecol.forEach((c, ind) => {
              if (c == key) {
                uel.changecol[ind] = newKey;
              }

            });
            console.log(uel.changecol);
          });
        }
      }
      newItem['updateCols'] = updatecols.find(e => e.nBundledetailid == newItem["nBundledetailid"])["changecol"];
      this.highlightCol = Array.from(new Set([].concat.apply([], updatecols.map(e => e.changecol))));
      return newItem;
    });
  }

  ishighlightCol(x) {
    if (this.highlightCol.length) {
      if (this.highlightCol.includes(x.dbkey))
        return true;
      else
        return false;
    }
    return false;

  }
}
